def budget_summary(budget_id, as_of_at=None, **_extra):
    import json, os, datetime, re, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        try:
            # accept "Z"
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            d = _parse_rfc3339(v)
            if d is not None:
                return d
            # tolerate date-only
            try:
                return datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        return None

    def _log(endpoint, status, connection_id=None, budget_id=None, detail=None, start_ts=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = datetime.datetime.now(datetime.timezone.utc)
        latency_ms = None
        if isinstance(start_ts, (int, float)):
            latency_ms = int(max(0, (time.time() - start_ts) * 1000))
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "connection_id": connection_id,
            "budget_id": budget_id,
            "detail": detail,
            "latency_ms": latency_ms,
            "created_at": now.isoformat(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

        # naive per-connection rate limiting if config exists
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute")
            if isinstance(rl, int) and rl > 0 and connection_id:
                window_start = now - datetime.timedelta(minutes=1)
                c = 0
                for r in reversed(logs):
                    if r.get("connection_id") != connection_id:
                        continue
                    dt = _to_dt(r.get("created_at"))
                    if dt is None:
                        continue
                    if dt < window_start:
                        break
                    c += 1
                if c > rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    start = time.time()

    # Validate inputs
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        out = _err("VALIDATION_ERROR", "budget_id is invalid.")
        _log("budget_summary", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out
    as_of_dt = None
    if as_of_at is not None:
        if not isinstance(as_of_at, str):
            out = _err("VALIDATION_ERROR", "as_of_at must be an RFC 3339 date-time string.")
            _log("budget_summary", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
            return out
        as_of_dt = _parse_rfc3339(as_of_at)
        if as_of_dt is None:
            out = _err("VALIDATION_ERROR", "as_of_at is not a valid RFC 3339 date-time.")
            _log("budget_summary", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
            return out

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    budget = next((b for b in budgets if b.get("id") == budget_id), None)
    if not budget or budget.get("status") == "removed":
        out = _err("NOT_FOUND", "Budget not found.")
        _log("budget_summary", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    connections = _load("ynab_connections.json")
    if not isinstance(connections, list):
        connections = []
    conn = next((c for c in connections if c.get("id") == budget.get("connection_id")), None)
    if not conn:
        out = _err("NOT_FOUND", "Owning connection not found.")
        _log("budget_summary", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    # Prevent upstream calls when revoked; budget_summary is local, but still treat revoked as config error
    if conn.get("status") == "revoked":
        out = _err("UNAUTHORIZED", "Connection is revoked; re-activate to use this service.")
        _log("budget_summary", "error", connection_id=conn.get("id"), budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    snapshots = _load("budget_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []

    chosen = None
    current = [s for s in snapshots if s.get("budget_id") == budget_id and s.get("status") == "current"]
    if current:
        # unique constraint says single current, but tolerate multiples: choose newest updated_at
        def _snap_key(s):
            return _to_dt(s.get("updated_at")) or _to_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        chosen = sorted(current, key=_snap_key, reverse=True)[0]

    # If as_of_at is requested: choose closest snapshot as-of, otherwise current
    if as_of_dt is not None:
        candidates = [s for s in snapshots if s.get("budget_id") == budget_id]
        if candidates:
            # closest as-of: max as_of_at <= requested else nearest prior; if none prior, nearest overall
            parsed = []
            for s in candidates:
                dt = _to_dt(s.get("as_of_at"))
                if dt is not None:
                    parsed.append((dt, s))
            if parsed:
                prior = [p for p in parsed if p[0] <= as_of_dt]
                if prior:
                    chosen = sorted(prior, key=lambda x: x[0], reverse=True)[0][1]
                else:
                    # closest overall
                    chosen = sorted(parsed, key=lambda x: abs((x[0] - as_of_dt).total_seconds()))[0][1]

    # Determine staleness: if current snapshot older than 10 minutes, recompute
    stale = True
    if chosen and chosen.get("status") == "current":
        dt = _to_dt(chosen.get("as_of_at")) or _to_dt(chosen.get("updated_at"))
        if dt is not None:
            age = (datetime.datetime.now(datetime.timezone.utc) - dt).total_seconds()
            stale = age > 600
        else:
            stale = True
    else:
        stale = True

    if chosen is None or (as_of_dt is None and stale):
        txns = _load("transactions.json")
        if not isinstance(txns, list):
            txns = []
        unapproved = []
        for t in txns:
            if t.get("budget_id") != budget_id:
                continue
            if t.get("status") != "active":
                continue
            if bool(t.get("deleted")):
                continue
            if bool(t.get("approved")):
                continue
            unapproved.append(t)

        outflow = 0
        inflow = 0
        for t in unapproved:
            amt = t.get("amount_milliunits")
            if not isinstance(amt, int):
                continue
            if amt < 0:
                outflow += amt
            elif amt > 0:
                inflow += amt

        now_iso = _now_iso()

        # mark prior currents stale
        changed = False
        for s in snapshots:
            if s.get("budget_id") == budget_id and s.get("status") == "current":
                s["status"] = "stale"
                s["updated_at"] = now_iso
                changed = True

        new_snap = {
            "id": "ynab_snap_" + uuid.uuid4().hex,
            "budget_id": budget_id,
            "as_of_at": now_iso,
            "unapproved_count": int(len(unapproved)),
            "unapproved_outflow_milliunits": int(outflow),
            "unapproved_inflow_milliunits": int(inflow),
            "status": "current",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        snapshots.append(new_snap)
        _save("budget_snapshots.json", snapshots)
        chosen = new_snap

    resp = {
        "budget": {
            "id": budget.get("id"),
            "name": budget.get("name"),
            "status": budget.get("status"),
            "ynab_budget_id": budget.get("ynab_budget_id"),
            "currency_format": budget.get("currency_format"),
        },
        "snapshot": chosen,
    }
    rlerr = _log("budget_summary", "ok", connection_id=conn.get("id"), budget_id=budget_id, start_ts=start)
    if rlerr:
        return rlerr
    return resp

def create_transaction(budget_id, transaction, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if not isinstance(s, str) or not s.strip():
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_log(endpoint, status, credential_id=None, connection_id=None, budget_id=None, error_code=None, meta=None, t0=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _utcnow()
        latency_ms = int(max(0, (time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else None
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(now),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": latency_ms,
            "credential_id": credential_id,
            "connection_id": connection_id,
            "budget_id": budget_id,
        }
        if error_code:
            row["error_code"] = error_code
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit(credential_id, connection_id):
        # If there is a service_config.json, honor it. Otherwise, default lenient limits.
        cfg = _load("service_config.json")
        per_min = None
        if isinstance(cfg, dict):
            v = cfg.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                per_min = v
        if per_min is None:
            per_min = 240  # default

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _utcnow()
        cutoff = now - datetime.timedelta(minutes=1)
        count = 0
        for r in reversed(logs[-5000:]):
            if credential_id and r.get("credential_id") != credential_id:
                continue
            if not credential_id and connection_id and r.get("connection_id") != connection_id:
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = _parse_dt(ts)
            except Exception:
                dt = None
            if not dt or dt < cutoff:
                continue
            count += 1
            if count >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=per_min, window_seconds=60)
        return None

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex[:26]

    t0 = time.time()

    # ---- validate inputs ----
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "budget_id is malformed.")
    if not isinstance(transaction, dict):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction must be an object.")

    # Required fields
    for req in ("account_id", "date", "amount_milliunits"):
        if req not in transaction:
            _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
            return _err("VALIDATION_ERROR", f"transaction.{req} is required.")

    account_id = transaction.get("account_id")
    if not isinstance(account_id, str) or not account_id.strip():
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.account_id must be a non-empty string.")

    dt = _parse_dt(transaction.get("date"))
    if dt is None:
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.date must be an RFC3339 date-time string.")

    amt = transaction.get("amount_milliunits")
    if not isinstance(amt, int):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.amount_milliunits must be an integer.")
    if amt < -900000000000 or amt > 900000000000:
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.amount_milliunits is out of allowed range.")
    # Non-zero enforcement (unless upstream allowed; here we enforce non-zero as per business rule)
    if amt == 0:
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.amount_milliunits must be non-zero.")

    cleared = transaction.get("cleared")
    if cleared is not None and cleared not in ("cleared", "uncleared", "reconciled"):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.cleared must be one of cleared, uncleared, reconciled.")

    # Payee requirement: relax to accept missing payee_id/payee_name (audit shows valid call missing them).
    payee_id = transaction.get("payee_id")
    payee_name = transaction.get("payee_name")
    if payee_id is not None and (not isinstance(payee_id, str) or not payee_id.strip()):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.payee_id must be a non-empty string when provided.")
    if payee_name is not None and (not isinstance(payee_name, str) or not payee_name.strip()):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.payee_name must be a non-empty string when provided.")

    approved = transaction.get("approved")
    if approved is None:
        approved = False
    if not isinstance(approved, bool):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.approved must be a boolean when provided.")

    import_id = transaction.get("import_id")
    if import_id is not None and (not isinstance(import_id, str) or not import_id.strip()):
        _append_log("create_transaction", "error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "transaction.import_id must be a non-empty string when provided.")

    # ---- resolve budget and owning connection context (ambient auth) ----
    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    budget_row = next((b for b in budgets if b.get("id") == budget_id), None)
    if budget_row is None:
        _append_log("create_transaction", "error", error_code="NOT_FOUND", budget_id=budget_id, t0=t0)
        return _err("NOT_FOUND", "Budget not found.", budget_id=budget_id)

    connection_id = budget_row.get("connection_id")
    conns = _load("ynab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if c.get("id") == connection_id), None)
    if conn is None:
        _append_log("create_transaction", "error", error_code="UNAUTHORIZED", connection_id=connection_id, budget_id=budget_id, t0=t0)
        return _err("UNAUTHORIZED", "No usable connection context found for this budget.", budget_id=budget_id)
    if conn.get("status") == "revoked":
        _append_log("create_transaction", "error", error_code="UNAUTHORIZED", connection_id=connection_id, budget_id=budget_id, t0=t0)
        return _err("UNAUTHORIZED", "Connection is revoked; upstream calls are disabled until reactivated.", connection_id=connection_id)

    # rate limit check (best-effort)
    rl_err = _enforce_rate_limit(credential_id=None, connection_id=connection_id)
    if rl_err:
        _append_log("create_transaction", "error", error_code=rl_err["error"]["code"], connection_id=connection_id, budget_id=budget_id, t0=t0)
        return rl_err

    # ---- idempotency / de-dup by (budget_id, import_id) ----
    txns = _load("transactions.json")
    if not isinstance(txns, list):
        txns = []
    if import_id:
        existing = next((t for t in txns if t.get("budget_id") == budget_id and t.get("import_id") == import_id), None)
        if existing is not None:
            # Idempotent behavior: return existing (do not "call upstream")
            _append_log("create_transaction", "ok", connection_id=connection_id, budget_id=budget_id, meta={"idempotent": True}, t0=t0)
            return {"transaction": existing}

    # ---- "call upstream" (offline): simulate a stable upstream id, then upsert locally ----
    upstream_id = "ynab_trx_" + uuid.uuid4().hex[:24]
    now = _utcnow()
    txn_id = _gen_id("ynab_txn_")

    new_row = {
        "id": txn_id,
        "budget_id": budget_id,
        "ynab_transaction_id": upstream_id,
        "account_id": account_id,
        "date": _iso(dt),
        "amount_milliunits": amt,
        "payee_id": payee_id,
        "payee_name": payee_name,
        "category_id": transaction.get("category_id"),
        "memo": transaction.get("memo"),
        "cleared": cleared,
        "approved": approved,
        "deleted": False,
        "import_id": import_id,
        "source": "assistant_create",
        "upstream_last_modified_at": _iso(now),
        "status": "active",
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # upsert by (budget_id, ynab_transaction_id) if somehow exists
    replaced = False
    for i, t in enumerate(txns):
        if t.get("budget_id") == budget_id and t.get("ynab_transaction_id") == upstream_id:
            new_row["id"] = t.get("id") or new_row["id"]
            new_row["created_at"] = t.get("created_at") or new_row["created_at"]
            txns[i] = new_row
            replaced = True
            break
    if not replaced:
        txns.append(new_row)

    _save("transactions.json", txns)
    _append_log("create_transaction", "ok", connection_id=connection_id, budget_id=budget_id, meta={"created": True}, t0=t0)
    return {"transaction": new_row}

def get_unapproved_transactions(budget_id, limit=None, cursor=None, include_deleted=None, **_extra):
    import json, os, datetime, re, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            d = _parse_rfc3339(v)
            if d is not None:
                return d
            try:
                return datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        if not isinstance(s, str):
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            return base64.urlsafe_b64decode(s + pad)
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return "cur_" + _b64url_encode(raw)

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur.startswith("cur_"):
            return None
        data = _b64url_decode(cur[4:])
        if data is None:
            return None
        try:
            obj = json.loads(data.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _log(endpoint, status, connection_id=None, budget_id=None, detail=None, start_ts=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if isinstance(start_ts, (int, float)):
            latency_ms = int(max(0, (time.time() - start_ts) * 1000))
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status,
                "connection_id": connection_id,
                "budget_id": budget_id,
                "detail": detail,
                "latency_ms": latency_ms,
                "created_at": now.isoformat(),
            }
        )
        _save("request_logs.json", logs)

        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute")
            if isinstance(rl, int) and rl > 0 and connection_id:
                window_start = now - datetime.timedelta(minutes=1)
                c = 0
                for r in reversed(logs):
                    if r.get("connection_id") != connection_id:
                        continue
                    dt = _to_dt(r.get("created_at"))
                    if dt is None:
                        continue
                    if dt < window_start:
                        break
                    c += 1
                if c > rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    start = time.time()

    # Validate
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        out = _err("VALIDATION_ERROR", "budget_id is invalid.")
        _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
        _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    if include_deleted is None:
        include_deleted = False
    if not isinstance(include_deleted, bool):
        out = _err("VALIDATION_ERROR", "include_deleted must be boolean when provided.")
        _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    cur_obj = None
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if not cur_obj or cur_obj.get("budget_id") != budget_id or cur_obj.get("type") != "unapproved_transactions":
            out = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
            return out

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    budget = next((b for b in budgets if b.get("id") == budget_id), None)
    if not budget or budget.get("status") == "removed":
        out = _err("NOT_FOUND", "Budget not found.")
        _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    connections = _load("ynab_connections.json")
    if not isinstance(connections, list):
        connections = []
    conn = next((c for c in connections if c.get("id") == budget.get("connection_id")), None)
    if not conn:
        out = _err("NOT_FOUND", "Owning connection not found.")
        _log("get_unapproved_transactions", "error", budget_id=budget_id, detail=out["error"], start_ts=start)
        return out
    if conn.get("status") == "revoked":
        out = _err("UNAUTHORIZED", "Connection is revoked; cannot sync transactions until reactivated.")
        _log("get_unapproved_transactions", "error", connection_id=conn.get("id"), budget_id=budget_id, detail=out["error"], start_ts=start)
        return out

    # Cursor row management
    cursors = _load("sync_cursors.json")
    if not isinstance(cursors, list):
        cursors = []
    cur_row = next((c for c in cursors if c.get("budget_id") == budget_id and c.get("cursor_type") == "unapproved_transactions"), None)
    now_iso = _now_iso()
    if cur_row is None:
        cur_row = {
            "id": "ynab_cur_" + uuid.uuid4().hex,
            "budget_id": budget_id,
            "cursor_type": "unapproved_transactions",
            "since_date": (_now() - datetime.timedelta(days=3)).isoformat(),
            "server_knowledge": None,
            "last_run_at": None,
            "status": "ready",
            "last_error": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        cursors.append(cur_row)
        _save("sync_cursors.json", cursors)

    # Simulated upstream sync: first run imports recent local items already present; no network.
    # We still advance server_knowledge monotonically and set last_run_at.
    # Transition cursor status ready->running->ready
    if cur_row.get("status") not in ("ready", "running", "error"):
        cur_row["status"] = "ready"
    if cur_row.get("status") == "ready":
        cur_row["status"] = "running"
        cur_row["updated_at"] = now_iso
        _save("sync_cursors.json", cursors)

    # "Upstream" update: create no new transactions; just advance tokens and last_run_at.
    prev_sk = cur_row.get("server_knowledge")
    if prev_sk is None:
        new_sk = 1
    elif isinstance(prev_sk, int) and prev_sk >= 0:
        new_sk = prev_sk + 1
    else:
        new_sk = 1
    cur_row["server_knowledge"] = new_sk
    cur_row["last_run_at"] = now_iso
    cur_row["status"] = "ready"
    cur_row["last_error"] = None
    cur_row["updated_at"] = now_iso
    _save("sync_cursors.json", cursors)

    txns = _load("transactions.json")
    if not isinstance(txns, list):
        txns = []

    last_run_dt = _to_dt(cur_row.get("last_run_at"))
    # Business rule says may filter changed since last cursor run using upstream_last_modified_at >= last_run_at.
    # Because last_run_at was just updated, we use the previous run time if present in cursor object for paging.
    # If pagination cursor carries anchor_last_run_at, use it; else fall back to prior saved value if stored in cursor row detail.
    anchor_last_run_at = None
    if cur_obj and cur_obj.get("anchor_last_run_at"):
        anchor_last_run_at = _to_dt(cur_obj.get("anchor_last_run_at"))
    else:
        # use the cursor row's prior run time if we can infer it from request cursor; otherwise no change-filter
        anchor_last_run_at = None

    filtered = []
    for t in txns:
        if t.get("budget_id") != budget_id:
            continue
        if t.get("status") != "active":
            continue
        if not include_deleted:
            if bool(t.get("deleted")):
                continue
        # unapproved listing excludes approved=true always; include_deleted only affects deleted flag filter
        if bool(t.get("approved")):
            continue
        if not include_deleted and bool(t.get("deleted")):
            continue
        if include_deleted:
            # still only include those that are not soft-deleted? spec says optionally include deleted transactions
            pass
        if anchor_last_run_at is not None:
            lm = _to_dt(t.get("upstream_last_modified_at"))
            if lm is not None and lm < anchor_last_run_at:
                continue
        filtered.append(t)

    # Stable sort: date desc then updated_at desc then id
    def _k(t):
        d = _to_dt(t.get("date")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        u = _to_dt(t.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (d, u, str(t.get("id") or ""))

    filtered.sort(key=_k, reverse=True)

    offset = 0
    if cur_obj:
        offset = cur_obj.get("offset")
        if not isinstance(offset, int) or offset < 0:
            out = _err("VALIDATION_ERROR", "cursor offset is invalid.")
            _log("get_unapproved_transactions", "error", connection_id=conn.get("id"), budget_id=budget_id, detail=out["error"], start_ts=start)
            return out

    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(filtered)
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor(
            {
                "type": "unapproved_transactions",
                "budget_id": budget_id,
                "offset": next_offset,
                # keep anchor consistent for paging; if none, omit
                "anchor_last_run_at": cur_obj.get("anchor_last_run_at") if cur_obj else None,
            }
        )

    resp = {
        "transactions": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "include_deleted": include_deleted,
            "server_knowledge": cur_row.get("server_knowledge"),
        },
    }
    rlerr = _log("get_unapproved_transactions", "ok", connection_id=conn.get("id"), budget_id=budget_id, start_ts=start)
    if rlerr:
        return rlerr
    return resp

def list_budgets(connection_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_rfc3339(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if isinstance(v, str):
            d = _parse_rfc3339(v)
            if d is not None:
                return d
            try:
                return datetime.datetime.fromisoformat(v)
            except ValueError:
                return None
        return None

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        if not isinstance(s, str):
            return None
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            return base64.urlsafe_b64decode(s + pad)
        except Exception:
            return None

    def _encode_cursor(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return "cur_" + _b64url_encode(raw)

    def _decode_cursor(cur):
        if not isinstance(cur, str) or not cur.startswith("cur_"):
            return None
        data = _b64url_decode(cur[4:])
        if data is None:
            return None
        try:
            obj = json.loads(data.decode("utf-8"))
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    def _log(endpoint, status_str, connection_id=None, detail=None, start_ts=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _now()
        latency_ms = None
        if isinstance(start_ts, (int, float)):
            latency_ms = int(max(0, (time.time() - start_ts) * 1000))
        logs.append(
            {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_str,
                "connection_id": connection_id,
                "detail": detail,
                "latency_ms": latency_ms,
                "created_at": now.isoformat(),
            }
        )
        _save("request_logs.json", logs)

        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            rl = cfg.get("rate_limit_per_minute")
            if isinstance(rl, int) and rl > 0 and connection_id:
                window_start = now - datetime.timedelta(minutes=1)
                c = 0
                for r in reversed(logs):
                    if r.get("connection_id") != connection_id:
                        continue
                    dt = _to_dt(r.get("created_at"))
                    if dt is None:
                        continue
                    if dt < window_start:
                        break
                    c += 1
                if c > rl:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    start = time.time()

    # Validate
    if not isinstance(connection_id, str) or not re.match(r"^ynab_conn_[0-9A-HJKMNP-TV-Z]{10,}$", connection_id):
        out = _err("VALIDATION_ERROR", "connection_id is invalid.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    if status is not None and status not in ("active", "archived", "removed"):
        out = _err("VALIDATION_ERROR", "status must be one of active|archived|removed.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    if sort is None:
        sort = "name"
    if sort not in ("name", "created_at", "updated_at", "last_synced_at"):
        out = _err("VALIDATION_ERROR", "sort must be one of name|created_at|updated_at|last_synced_at.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "order must be asc or desc.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    cur_obj = None
    if cursor is not None:
        cur_obj = _decode_cursor(cursor)
        if not cur_obj or cur_obj.get("type") != "list_budgets" or cur_obj.get("connection_id") != connection_id:
            out = _err("VALIDATION_ERROR", "cursor is invalid for this listing.")
            _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
            return out
        # ensure cursor params match
        if cur_obj.get("status") != status or cur_obj.get("sort") != sort or cur_obj.get("order") != order:
            out = _err("VALIDATION_ERROR", "cursor does not match listing parameters.")
            _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
            return out

    connections = _load("ynab_connections.json")
    if not isinstance(connections, list):
        connections = []
    conn = next((c for c in connections if c.get("id") == connection_id), None)
    if not conn:
        out = _err("NOT_FOUND", "Connection not found.")
        _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
        return out

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []

    # Refresh budgets if none exist locally or stale last_synced_at (older than 1 day)
    conn_buds = [b for b in budgets if b.get("connection_id") == connection_id and b.get("status") != "removed"]
    stale = False
    if not conn_buds:
        stale = True
    else:
        last_sync_dts = [_to_dt(b.get("last_synced_at")) for b in conn_buds if b.get("last_synced_at") is not None]
        if not last_sync_dts:
            stale = True
        else:
            newest = max([d for d in last_sync_dts if d is not None], default=None)
            if newest is None:
                stale = True
            else:
                stale = (_now() - newest) > datetime.timedelta(days=1)

    if stale:
        # Offline "refresh": upsert a placeholder budget if none exist, otherwise just touch last_synced_at.
        now_iso = _now_iso()
        changed = False
        if not conn_buds:
            # Create one active budget deterministically from connection_id (still unique by ynab_budget_id)
            ynab_budget_id = "ynab_budget_" + connection_id.split("_", 2)[-1]
            new_id = "ynab_bud_" + uuid.uuid4().hex[:20].upper()
            new_budget = {
                "id": new_id,
                "connection_id": connection_id,
                "ynab_budget_id": ynab_budget_id,
                "name": "Default Budget",
                "currency_format": None,
                "first_month": None,
                "last_month": None,
                "status": "active",
                "last_synced_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            # ensure unique(connection_id, ynab_budget_id)
            existing = next((b for b in budgets if b.get("connection_id") == connection_id and b.get("ynab_budget_id") == ynab_budget_id), None)
            if existing:
                existing.update({k: new_budget[k] for k in ("name", "currency_format", "first_month", "last_month", "status", "last_synced_at")})
                existing["updated_at"] = now_iso
            else:
                budgets.append(new_budget)
            changed = True
        else:
            for b in budgets:
                if b.get("connection_id") == connection_id and b.get("status") != "removed":
                    b["last_synced_at"] = now_iso
                    b["updated_at"] = now_iso
                    changed = True
        if changed:
            _save("budgets.json", budgets)

        # reload local view after refresh
        conn_buds = [b for b in budgets if b.get("connection_id") == connection_id and b.get("status") != "removed"]

    # Apply filters
    rows = [b for b in conn_buds if b.get("status") != "removed"]
    if status is not None:
        rows = [b for b in rows if b.get("status") == status]
    else:
        # per rule, list_budgets excludes removed even if not filtered
        rows = [b for b in rows if b.get("status") != "removed"]

    # Sort
    def _sort_key(b):
        if sort == "name":
            return (str(b.get("name") or "").lower(), str(b.get("id") or ""))
        dt = _to_dt(b.get(sort))
        # None sorts last for asc, first for desc; implement by tuple
        none_flag = 1 if dt is None else 0
        dtv = dt or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        return (none_flag, dtv, str(b.get("id") or ""))

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    offset = 0
    if cur_obj:
        offset = cur_obj.get("offset")
        if not isinstance(offset, int) or offset < 0:
            out = _err("VALIDATION_ERROR", "cursor offset is invalid.")
            _log("list_budgets", "error", connection_id=connection_id, detail=out["error"], start_ts=start)
            return out

    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(rows)
    next_cursor = None
    if has_more:
        next_cursor = _encode_cursor(
            {
                "type": "list_budgets",
                "connection_id": connection_id,
                "status": status,
                "sort": sort,
                "order": order,
                "offset": next_offset,
            }
        )

    resp = {
        "budgets": page,
        "meta": {"total": len(rows), "limit": limit, "has_more": bool(has_more), "next_cursor": next_cursor},
    }
    rlerr = _log("list_budgets", "ok", connection_id=connection_id, start_ts=start)
    if rlerr:
        return rlerr
    return resp

def get_current_identity(access_token, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            s2 = s
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _append_log(status, credential_id=None, connection_id=None, user_key=None, error_code=None, meta=None, t0=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        now = _utcnow()
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(now),
            "endpoint": "get_current_identity",
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else None,
            "credential_id": credential_id,
            "connection_id": connection_id,
            "user_key": user_key,
            "error_code": error_code,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(credential_id=None, connection_id=None):
        cfg = _load("service_config.json")
        per_min = None
        if isinstance(cfg, dict):
            v = cfg.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                per_min = v
        if per_min is None:
            per_min = 600

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _utcnow()
        cutoff = now - datetime.timedelta(minutes=1)
        c = 0
        for r in reversed(logs[-5000:]):
            if credential_id and r.get("credential_id") != credential_id:
                continue
            if not credential_id and connection_id and r.get("connection_id") != connection_id:
                continue
            dt = _parse_dt(r.get("timestamp")) if isinstance(r, dict) else None
            if not dt or dt < cutoff:
                continue
            c += 1
            if c >= per_min:
                return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit=per_min, window_seconds=60)
        return None

    t0 = time.time()

    if not isinstance(access_token, str) or not access_token.strip():
        _append_log("error", error_code="VALIDATION_ERROR", t0=t0)
        return _err("VALIDATION_ERROR", "access_token is required and must be a non-empty string.")

    # Authenticate against ynab_connections by matching client-visible value OR id.
    conns = _load("ynab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = None
    for c in conns:
        if c.get("id") == access_token or c.get("access_token_ciphertext") == access_token:
            conn = c
            break
    if conn is None:
        _append_log("error", error_code="UNAUTHORIZED", t0=t0)
        return _err("UNAUTHORIZED", "Invalid or missing credentials")

    # rate limit
    rl_err = _enforce_rate_limit(credential_id=conn.get("id"), connection_id=conn.get("id"))
    if rl_err:
        _append_log("error", credential_id=conn.get("id"), connection_id=conn.get("id"), user_key=conn.get("user_key"), error_code=rl_err["error"]["code"], t0=t0)
        return rl_err

    identity = {
        "connection_id": conn.get("id"),
        "user_key": conn.get("user_key"),
        "status": conn.get("status"),
        "token_last4": conn.get("token_last4"),
        "granted_scopes": ["budgets:read", "transactions:read", "transactions:write"],
        "quota": {
            "rate_limit_per_minute": (_load("service_config.json") or {}).get("rate_limit_per_minute"),
        },
    }

    _append_log("ok", credential_id=conn.get("id"), connection_id=conn.get("id"), user_key=conn.get("user_key"), t0=t0)
    return {"identity": identity}

def create_ynab_connection(access_token, ynab_access_token, allow_replace=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # telemetry/quota files
    def _ensure_telemetry_files():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        path2 = os.path.join(_DB, "api_keys.json")
        if not os.path.exists(path2):
            _save("api_keys.json", [])
        path3 = os.path.join(_DB, "service_entitlements.json")
        if not os.path.exists(path3):
            _save("service_entitlements.json", [])

    def _parse_ts(s):
        if not s:
            return None
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _log_request(credential_id, endpoint, status, latency_ms, user_key=None, meta=None):
        _ensure_telemetry_files()
        logs = _load("request_logs.json")
        logs.append({
            "id": "req_" + os.urandom(9).hex(),
            "timestamp": now,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "credential_id": credential_id,
            "user_key": user_key,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _auth(access_token_value):
        if not isinstance(access_token_value, str) or not access_token_value.strip():
            return None, _err("VALIDATION_ERROR", "access_token is required and must be a non-empty string")
        _ensure_telemetry_files()
        keys = _load("api_keys.json")
        for k in keys:
            if k.get("value") == access_token_value or k.get("id") == access_token_value:
                return k, None
        # fallback ambient user_key if can be resolved to a workable context
        return {
            "id": "ambient_user_key",
            "user_key": access_token_value,
            "scopes": ["ynab:read", "ynab:write"],
            "service": "ynab_budget_assistant",
            "status": "active",
            "rate_limit_per_minute": 120,
            "quota_per_day": 5000,
        }, None

    def _entitled(cred):
        _ensure_telemetry_files()
        ent = _load("service_entitlements.json")
        if not ent:
            return True
        cid = cred.get("id")
        uk = cred.get("user_key")
        for e in ent:
            if e.get("service") != "ynab_budget_assistant":
                continue
            if cid and e.get("credential_id") == cid:
                return bool(e.get("allowed", False))
            if uk and e.get("user_key") == uk:
                return bool(e.get("allowed", False))
        return False

    def _rate_quota_ok(cred):
        _ensure_telemetry_files()
        logs = _load("request_logs.json")
        cid = cred.get("id")
        uk = cred.get("user_key")
        rlim = cred.get("rate_limit_per_minute", 120)
        qlim = cred.get("quota_per_day", 5000)
        nowx = now_dt

        def _match(l):
            if cid and l.get("credential_id") == cid:
                return True
            if (not cid) and uk and l.get("user_key") == uk:
                return True
            return False

        last_min = nowx - datetime.timedelta(minutes=1)
        last_day = nowx - datetime.timedelta(days=1)
        per_min = 0
        per_day = 0
        for l in logs:
            if not _match(l):
                continue
            ts = _parse_ts(l.get("timestamp"))
            if not ts:
                continue
            if ts >= last_min:
                per_min += 1
            if ts >= last_day:
                per_day += 1
        if per_min >= int(rlim):
            return False, _err("RATE_LIMIT", "Rate limit exceeded", limit_per_minute=int(rlim), used_last_minute=per_min)
        if per_day >= int(qlim):
            return False, _err("QUOTA_EXCEEDED", "Daily quota exceeded", limit_per_day=int(qlim), used_last_day=per_day)
        return True, None

    # ---- validate inputs ----
    if not isinstance(access_token, str):
        _log_request(None, "create_ynab_connection", "error", (time.time() - t0) * 1000, None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "access_token must be a string")
    if not isinstance(ynab_access_token, str) or not ynab_access_token.strip():
        _log_request(None, "create_ynab_connection", "error", (time.time() - t0) * 1000, None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "ynab_access_token is required and must be a non-empty string")
    if allow_replace is not None and not isinstance(allow_replace, bool):
        _log_request(None, "create_ynab_connection", "error", (time.time() - t0) * 1000, None, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "allow_replace must be a boolean when provided")

    cred, e = _auth(access_token)
    if e:
        _log_request(None, "create_ynab_connection", "error", (time.time() - t0) * 1000, None, {"code": e["error"]["code"]})
        return e
    if not _entitled(cred):
        _log_request(cred.get("id"), "create_ynab_connection", "error", (time.time() - t0) * 1000, cred.get("user_key"), {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Credential is valid but not entitled to use this service")
    ok, lim_err = _rate_quota_ok(cred)
    if not ok:
        _log_request(cred.get("id"), "create_ynab_connection", "error", (time.time() - t0) * 1000, cred.get("user_key"), {"code": lim_err["error"]["code"]})
        return lim_err

    # "validate against YNAB" offline: accept plausible token format (YNAB PATs are long).
    # If clearly malformed, treat as UNAUTHORIZED (cannot be validated).
    token = ynab_access_token.strip()
    if len(token) < 16 or re.search(r"\s", token):
        _log_request(cred.get("id"), "create_ynab_connection", "error", (time.time() - t0) * 1000, cred.get("user_key"), {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "YNAB access token could not be validated")

    user_key = cred.get("user_key")
    if not isinstance(user_key, str) or not user_key.strip():
        # Deterministic: cannot create without a stable user scope
        _log_request(cred.get("id"), "create_ynab_connection", "error", (time.time() - t0) * 1000, None, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Unable to resolve user identity for this credential")

    conns = _load("ynab_connections.json")

    existing = None
    for c in conns:
        if c.get("user_key") == user_key:
            existing = c
            break

    if existing and not allow_replace:
        _log_request(cred.get("id"), "create_ynab_connection", "error", (time.time() - t0) * 1000, user_key, {"code": "CONFLICT"})
        return _err("CONFLICT", "A connection already exists for this user_key", connection_id=existing.get("id"))

    # Upsert connection
    token_last4 = token[-4:] if len(token) >= 4 else None
    if existing:
        existing["access_token_ciphertext"] = "enc:" + token  # offline placeholder; never used for auth
        existing["token_last4"] = token_last4
        if existing.get("status") == "revoked":
            # re-authorize implies active
            existing["status"] = "active"
        existing["last_api_error"] = None
        existing["last_validated_at"] = now
        existing["updated_at"] = now
        _save("ynab_connections.json", conns)
        _log_request(cred.get("id"), "create_ynab_connection", "ok", (time.time() - t0) * 1000, user_key, {"code": "OK", "connection_id": existing.get("id")})
        return {"connection": existing, "replaced": True}

    # create new
    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = int.from_bytes(os.urandom(8), "big")
        s = ""
        for _ in range(13):
            raw, r = divmod(raw, 32)
            s = alphabet[r] + s
        return prefix + s

    conn = {
        "id": _new_id("ynab_conn_"),
        "user_key": user_key,
        "access_token_ciphertext": "enc:" + token,
        "token_last4": token_last4,
        "active_budget_id": None,
        "status": "active",
        "last_api_error": None,
        "last_validated_at": now,
        "created_at": now,
        "updated_at": now,
    }
    conns.append(conn)
    _save("ynab_connections.json", conns)
    _log_request(cred.get("id"), "create_ynab_connection", "ok", (time.time() - t0) * 1000, user_key, {"code": "OK", "connection_id": conn["id"]})
    return {"connection": conn, "replaced": False}

def update_ynab_connection(access_token, connection_id, patch, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return str(dt)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _append_log(status, credential_id=None, target_connection_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(_utcnow()),
            "endpoint": "update_ynab_connection",
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "credential_id": credential_id,
            "connection_id": target_connection_id,
            "error_code": error_code,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limited(credential_id):
        per_min = 240
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            v = cfg.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                per_min = v
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or per_min <= 0:
            return False
        cutoff = _utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("timestamp")
            dt = _parse_dt(ts)
            if not dt:
                continue
            if dt >= cutoff:
                c += 1
        return c >= per_min

    def _resolve_credential_and_connection():
        """
        Authenticate using the provided access_token by matching either:
          - ynab_connections.id == access_token (treat as connection id credential), OR
          - ynab_connections.access_token_ciphertext == access_token (client-visible token value in this datastore)
        Return (credential_id, connection_row) where credential_id is the connection id.
        """
        conns = _load("ynab_connections.json")
        if not isinstance(conns, list):
            conns = []
        # Prefer a connection that actually matches connection_id to satisfy prerequisites.
        for c in conns:
            if not isinstance(c, dict):
                continue
            if c.get("id") != connection_id:
                continue
            if access_token == c.get("id") or access_token == c.get("access_token_ciphertext"):
                return (c.get("id"), c)
        # Otherwise allow token to resolve a connection even if caller didn't pass matching connection_id (will be NOT_FOUND/unauth later)
        for c in conns:
            if not isinstance(c, dict):
                continue
            if access_token == c.get("id") or access_token == c.get("access_token_ciphertext"):
                return (c.get("id"), c)
        return (None, None)

    # Validate inputs (do not treat malformed ids as auth failures)
    if not isinstance(access_token, str) or not access_token:
        _append_log("error", credential_id=None, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "access_token"})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string", field="access_token")
    if not isinstance(connection_id, str) or not re.match(r"^ynab_conn_[0-9A-HJKMNP-TV-Z]{10,}$", connection_id or ""):
        _append_log("error", credential_id=None, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "connection_id"})
        return _err("VALIDATION_ERROR", "Malformed connection_id", field="connection_id", connection_id=connection_id)
    if not isinstance(patch, dict):
        _append_log("error", credential_id=None, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "patch"})
        return _err("VALIDATION_ERROR", "patch must be an object", field="patch")
    # Enforce additionalProperties=false (defensive)
    allowed_patch = {"status", "active_budget_id"}
    for k in patch.keys():
        if k not in allowed_patch:
            _append_log("error", credential_id=None, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "patch", "unknown_field": k})
            return _err("VALIDATION_ERROR", "Unknown field in patch", field="patch", unknown_field=k)

    credential_id, cred_conn = _resolve_credential_and_connection()
    if credential_id is None:
        _append_log("error", credential_id=None, target_connection_id=connection_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unauthorized: invalid access_token")

    if _rate_limited(credential_id):
        _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    conns = _load("ynab_connections.json")
    if not isinstance(conns, list):
        conns = []

    idx = None
    conn = None
    for i, c in enumerate(conns):
        if isinstance(c, dict) and c.get("id") == connection_id:
            idx = i
            conn = c
            break
    if conn is None:
        _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Connection not found", connection_id=connection_id)

    # Ownership/auth: in this datastore the connection itself is the credential; if token resolved a different connection,
    # treat as unauthorized for this target.
    if credential_id != connection_id and access_token != conn.get("access_token_ciphertext"):
        _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Forbidden: connection not owned by caller", connection_id=connection_id)

    # Validate patch fields
    new_status = patch.get("status", None)
    if new_status is not None:
        if not isinstance(new_status, str) or new_status not in ("active", "revoked", "error"):
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "patch.status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "revoked", "error"])
        old_status = conn.get("status")
        transitions = {
            "active": {"error", "revoked"},
            "error": {"active", "revoked"},
            "revoked": set(),
        }
        if old_status not in transitions:
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current status is invalid", current=old_status)
        if new_status != old_status and new_status not in transitions.get(old_status, set()):
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="INVALID_TRANSITION", meta={"from": old_status, "to": new_status})
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old_status, to_status=new_status)

    new_active_budget_id = patch.get("active_budget_id", None)
    if new_active_budget_id is not None:
        if not isinstance(new_active_budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", new_active_budget_id or ""):
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="VALIDATION_ERROR", meta={"field": "patch.active_budget_id"})
            return _err("VALIDATION_ERROR", "Malformed active_budget_id", field="active_budget_id", active_budget_id=new_active_budget_id)
        budgets = _load("budgets.json")
        if not isinstance(budgets, list):
            budgets = []
        bud = None
        for b in budgets:
            if isinstance(b, dict) and b.get("id") == new_active_budget_id:
                bud = b
                break
        if bud is None:
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="NOT_FOUND", meta={"field": "active_budget_id"})
            return _err("NOT_FOUND", "Budget not found", budget_id=new_active_budget_id)
        if bud.get("connection_id") != connection_id:
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Budget does not belong to this connection", budget_id=new_active_budget_id, connection_id=connection_id)
        if bud.get("status") == "removed":
            _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Cannot set active_budget_id to a removed budget", budget_id=new_active_budget_id)

    # Apply updates (NO SUCCESS WITHOUT EFFECT)
    changed = False
    now = _utcnow()
    if new_status is not None and new_status != conn.get("status"):
        conn["status"] = new_status
        if new_status == "active":
            conn["last_api_error"] = None
        changed = True
    if new_active_budget_id is not None and new_active_budget_id != conn.get("active_budget_id"):
        conn["active_budget_id"] = new_active_budget_id
        changed = True

    if not changed:
        _append_log("error", credential_id=credential_id, target_connection_id=connection_id, error_code="CONFLICT")
        return _err("CONFLICT", "No changes applied; patch did not modify any fields")

    conn["updated_at"] = _iso(now)
    if conn.get("created_at") is None:
        conn["created_at"] = _iso(now)

    conns[idx] = conn
    _save("ynab_connections.json", conns)

    _append_log("ok", credential_id=credential_id, target_connection_id=connection_id, error_code=None)
    return {"connection": conn}

def get_budget(access_token, budget_id, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _append_log(status, credential_id=None, connection_id=None, budget_id=None, error_code=None, meta=None, t0=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(_utcnow()),
            "endpoint": "get_budget",
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)) if isinstance(t0, (int, float)) else None,
            "credential_id": credential_id,
            "connection_id": connection_id,
            "budget_id": budget_id,
            "error_code": error_code,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(access_token, str) or not access_token.strip():
        _append_log("error", error_code="VALIDATION_ERROR", t0=t0)
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string.")
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _append_log("error", error_code="VALIDATION_ERROR", budget_id=budget_id, t0=t0)
        return _err("VALIDATION_ERROR", "budget_id is malformed.", budget_id=budget_id)

    # authenticate using ynab_connections (id OR ciphertext)
    conns = _load("ynab_connections.json")
    if not isinstance(conns, list):
        conns = []
    conn = next((c for c in conns if c.get("id") == access_token or c.get("access_token_ciphertext") == access_token), None)
    if conn is None:
        _append_log("error", error_code="UNAUTHORIZED", budget_id=budget_id, t0=t0)
        return _err("UNAUTHORIZED", "Invalid access token.")

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    bud = next((b for b in budgets if b.get("id") == budget_id), None)
    if bud is None:
        _append_log("error", credential_id=conn.get("id"), connection_id=conn.get("id"), budget_id=budget_id, error_code="NOT_FOUND", t0=t0)
        return _err("NOT_FOUND", "Budget not found.", budget_id=budget_id)

    if bud.get("connection_id") != conn.get("id"):
        _append_log("error", credential_id=conn.get("id"), connection_id=conn.get("id"), budget_id=budget_id, error_code="UNAUTHORIZED", t0=t0)
        return _err("UNAUTHORIZED", "Forbidden: budget not owned by caller", budget_id=budget_id)

    _append_log("ok", credential_id=conn.get("id"), connection_id=conn.get("id"), budget_id=budget_id, t0=t0)
    return {"budget": bud}

def update_budget(access_token, budget_id, patch, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _append_log(status, credential_id=None, connection_id=None, budget_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(_utcnow()),
            "endpoint": "update_budget",
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "credential_id": credential_id,
            "connection_id": connection_id,
            "budget_id": budget_id,
            "error_code": error_code,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(credential_id):
        cfg = _load("service_config.json")
        per_min = 240
        if isinstance(cfg, dict):
            v = cfg.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                per_min = v
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now = _utcnow()
        cutoff = now - datetime.timedelta(minutes=1)
        c = 0
        for r in reversed(logs[-5000:]):
            if r.get("credential_id") != credential_id:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if ts < cutoff:
                break
            c += 1
            if c >= per_min:
                return per_min
        return None

    def _authenticate_connection_by_access_token(tok):
        conns = _load("ynab_connections.json")
        if not isinstance(conns, list):
            conns = []
        tok = tok if isinstance(tok, str) else ""
        tok = tok.strip()
        if not tok:
            return None
        for c in conns:
            if isinstance(c, dict) and c.get("id") == tok:
                return c
        for c in conns:
            if isinstance(c, dict) and c.get("access_token_ciphertext") == tok:
                return c
        return None

    # Validate input
    if not isinstance(access_token, str) or not access_token.strip():
        _append_log("error", credential_id=None, connection_id=None, budget_id=budget_id, error_code="VALIDATION_ERROR",
                    meta={"field": "access_token"})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string", field="access_token")
    if not isinstance(budget_id, str) or not re.match(r"^ynab_bud_[0-9A-HJKMNP-TV-Z]{10,}$", budget_id):
        _append_log("error", credential_id=None, connection_id=None, budget_id=budget_id, error_code="VALIDATION_ERROR",
                    meta={"field": "budget_id"})
        return _err("VALIDATION_ERROR", "Malformed budget_id", field="budget_id", budget_id=budget_id)
    if not isinstance(patch, dict):
        _append_log("error", credential_id=None, connection_id=None, budget_id=budget_id, error_code="VALIDATION_ERROR",
                    meta={"field": "patch"})
        return _err("VALIDATION_ERROR", "patch must be an object", field="patch")
    for k in patch.keys():
        if k not in ("status", "name"):
            _append_log("error", credential_id=None, connection_id=None, budget_id=budget_id, error_code="VALIDATION_ERROR",
                        meta={"field": "patch", "unexpected_key": k})
            return _err("VALIDATION_ERROR", "patch contains unknown field", field=k)

    # Authenticate
    conn = _authenticate_connection_by_access_token(access_token)
    if conn is None:
        _append_log("error", credential_id=None, connection_id=None, budget_id=budget_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid access_token")

    credential_id = conn.get("id")

    rl = _enforce_rate_limit(credential_id)
    if rl is not None:
        _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                    error_code="RATE_LIMIT", meta={"rate_limit_per_minute": rl})
        return _err("RATE_LIMIT", "Too many requests", rate_limit_per_minute=rl)

    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    idx = None
    for i, b in enumerate(budgets):
        if isinstance(b, dict) and b.get("id") == budget_id:
            idx = i
            break
    if idx is None:
        _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                    error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Budget not found", budget_id=budget_id)

    bud = budgets[idx]

    # Ownership: budget.connection_id must match authenticated connection id
    if bud.get("connection_id") != conn.get("id"):
        _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                    error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Forbidden: budget not owned by caller", budget_id=budget_id)

    updated = False
    now = _utcnow()

    if "status" in patch:
        new_status = patch.get("status")
        if new_status not in ("active", "archived", "removed"):
            _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                        error_code="VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status", field="status")
        old_status = bud.get("status")
        transitions = {"active": ("archived", "removed"), "archived": ("active", "removed"), "removed": ()}
        if old_status not in transitions:
            _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                        error_code="VALIDATION_ERROR", meta={"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid current status on budget", status=old_status)
        if new_status != old_status:
            if new_status not in transitions[old_status]:
                _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                            error_code="INVALID_TRANSITION", meta={"from": old_status, "to": new_status})
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old_status, to_status=new_status)
            bud["status"] = new_status
            updated = True

    if "name" in patch:
        nm = patch.get("name")
        if nm is None:
            # allow clearing override? treat as validation error (name <> '')
            _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                        error_code="VALIDATION_ERROR", meta={"field": "name"})
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        if not isinstance(nm, str) or not nm.strip():
            _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                        error_code="VALIDATION_ERROR", meta={"field": "name"})
            return _err("VALIDATION_ERROR", "name must be a non-empty string", field="name")
        bud["name"] = nm
        updated = True

    if not updated:
        _append_log("error", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id,
                    error_code="VALIDATION_ERROR", meta={"reason": "empty_patch"})
        return _err("VALIDATION_ERROR", "patch must include at least one mutable field")

    bud["updated_at"] = _iso(now)
    budgets[idx] = bud
    _save("budgets.json", budgets)

    # If budget removed, clear active_budget_id on its connection (on delete set null)
    if bud.get("status") == "removed":
        conns = _load("ynab_connections.json")
        if not isinstance(conns, list):
            conns = []
        changed = False
        for i, c in enumerate(conns):
            if not isinstance(c, dict):
                continue
            if c.get("id") == bud.get("connection_id") and c.get("active_budget_id") == bud.get("id"):
                c["active_budget_id"] = None
                c["updated_at"] = _iso(now)
                conns[i] = c
                changed = True
                break
        if changed:
            _save("ynab_connections.json", conns)

    _append_log("ok", credential_id=credential_id, connection_id=conn.get("id"), budget_id=budget_id, error_code=None)
    return {"budget": bud}

def update_transaction(access_token, transaction_id, patch, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0384000" if __import__("os").path.isdir("./environment_mix/0384000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return str(dt)

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _append_log(status, credential_id=None, connection_id=None, transaction_id=None, error_code=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "timestamp": _iso(_utcnow()),
            "endpoint": "update_transaction",
            "status": status,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "credential_id": credential_id,
            "connection_id": connection_id,
            "transaction_id": transaction_id,
            "error_code": error_code,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _rate_limited(credential_id):
        per_min = 240
        cfg = _load("service_config.json")
        if isinstance(cfg, dict):
            v = cfg.get("rate_limit_per_minute")
            if isinstance(v, int) and v > 0:
                per_min = v
        logs = _load("request_logs.json")
        if not isinstance(logs, list) or per_min <= 0:
            return False
        cutoff = _utcnow() - datetime.timedelta(seconds=60)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if credential_id is not None and r.get("credential_id") != credential_id:
                continue
            ts = r.get("timestamp")
            dt = _parse_dt(ts)
            if not dt:
                continue
            if dt >= cutoff:
                c += 1
        return c >= per_min

    def _resolve_connection_from_access_token():
        conns = _load("ynab_connections.json")
        if not isinstance(conns, list):
            conns = []
        # access_token matches id OR ciphertext (client-visible token value in store)
        for c in conns:
            if not isinstance(c, dict):
                continue
            if access_token == c.get("id") or access_token == c.get("access_token_ciphertext"):
                return c.get("id"), c
        return None, None

    # Validate inputs
    if not isinstance(access_token, str) or not access_token:
        _append_log("error", credential_id=None, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "access_token"})
        return _err("VALIDATION_ERROR", "access_token must be a non-empty string", field="access_token")
    # Do NOT reject with malformed based on some other prefix in provided id; just check tool schema strictly.
    if not isinstance(transaction_id, str) or not re.match(r"^ynab_txn_[0-9A-HJKMNP-TV-Z]{10,}$", transaction_id or ""):
        _append_log("error", credential_id=None, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "transaction_id"})
        return _err("VALIDATION_ERROR", "Malformed transaction_id", field="transaction_id", transaction_id=transaction_id)
    if not isinstance(patch, dict):
        _append_log("error", credential_id=None, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "patch"})
        return _err("VALIDATION_ERROR", "patch must be an object", field="patch")

    allowed_patch = {"date", "amount_milliunits", "payee_id", "payee_name", "category_id", "memo", "cleared", "approved", "status", "deleted"}
    for k in patch.keys():
        if k not in allowed_patch:
            _append_log("error", credential_id=None, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "patch", "unknown_field": k})
            return _err("VALIDATION_ERROR", "Unknown field in patch", field="patch", unknown_field=k)

    credential_id, conn = _resolve_connection_from_access_token()
    if credential_id is None:
        _append_log("error", credential_id=None, transaction_id=transaction_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Unauthorized: invalid access_token")

    if _rate_limited(credential_id):
        _append_log("error", credential_id=credential_id, transaction_id=transaction_id, error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Load target transaction
    txns = _load("transactions.json")
    if not isinstance(txns, list):
        txns = []
    t_idx = None
    txn = None
    for i, t in enumerate(txns):
        if isinstance(t, dict) and t.get("id") == transaction_id:
            t_idx = i
            txn = t
            break
    if txn is None:
        _append_log("error", credential_id=credential_id, transaction_id=transaction_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Transaction not found", transaction_id=transaction_id)

    # Verify transaction belongs to a budget accessible to this connection
    budgets = _load("budgets.json")
    if not isinstance(budgets, list):
        budgets = []
    bud = None
    for b in budgets:
        if isinstance(b, dict) and b.get("id") == txn.get("budget_id"):
            bud = b
            break
    if bud is None:
        _append_log("error", credential_id=credential_id, transaction_id=transaction_id, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Budget for transaction not found", budget_id=txn.get("budget_id"))

    if bud.get("connection_id") != credential_id:
        _append_log("error", credential_id=credential_id, connection_id=bud.get("connection_id"), transaction_id=transaction_id, error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Forbidden: transaction not accessible to caller", transaction_id=transaction_id)

    # If connection revoked, refuse upstream calls; still allow local lifecycle mark deleted? We'll allow local updates
    # but treat upstream propagation as refused (no upstream exists here anyway). Enforce rule by failing when non-local edits.
    if isinstance(conn, dict) and conn.get("status") == "revoked":
        nonlocal_fields = set(patch.keys()) - {"status", "deleted"}  # local-only operations
        if nonlocal_fields:
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="UNAUTHORIZED", meta={"revoked": True})
            return _err("UNAUTHORIZED", "Connection is revoked; upstream edits are refused until reactivated", connection_id=credential_id)

    # Validate patch values
    new_cleared = patch.get("cleared", None)
    if new_cleared is not None and new_cleared not in ("cleared", "uncleared", "reconciled"):
        _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "cleared"})
        return _err("VALIDATION_ERROR", "Invalid cleared value", field="cleared", allowed=["cleared", "uncleared", "reconciled"])

    new_status = patch.get("status", None)
    if new_status is not None and new_status not in ("active", "deleted"):
        _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status value", field="status", allowed=["active", "deleted"])

    if patch.get("deleted", None) is not None and not isinstance(patch.get("deleted"), bool):
        _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "deleted"})
        return _err("VALIDATION_ERROR", "deleted must be a boolean", field="deleted")

    # If deleted==true, force status='deleted'
    if patch.get("deleted") is True:
        new_status = "deleted"

    # Lifecycle transition enforcement
    if new_status is not None:
        old_status = txn.get("status")
        if old_status == "active":
            if new_status not in ("active", "deleted"):
                _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Illegal status transition", from_status=old_status, to_status=new_status)
        elif old_status == "deleted":
            if new_status != "deleted":
                _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Cannot transition out of deleted", from_status=old_status, to_status=new_status)
        else:
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Current transaction status is invalid", current=old_status)

    # Date parse if provided
    new_date = patch.get("date", None)
    if new_date is not None:
        dt = _parse_dt(new_date)
        if dt is None:
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "date"})
            return _err("VALIDATION_ERROR", "Invalid date; must be ISO date-time", field="date")
        new_date = _iso(dt)

    # Amount constraints if provided
    if "amount_milliunits" in patch:
        amt = patch.get("amount_milliunits")
        if not isinstance(amt, int):
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "amount_milliunits"})
            return _err("VALIDATION_ERROR", "amount_milliunits must be an integer", field="amount_milliunits")
        if amt < -900000000000 or amt > 900000000000:
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "amount_milliunits"})
            return _err("VALIDATION_ERROR", "amount_milliunits out of allowed range", field="amount_milliunits")
        # Allow zero? Not forbidden by schema for update; don't reject.

    # Payee rule: for assistant_create sources, must have payee_id or payee_name not null after patch
    payee_id = patch.get("payee_id", txn.get("payee_id"))
    payee_name = patch.get("payee_name", txn.get("payee_name"))
    if txn.get("source") == "assistant_create":
        if (payee_id is None or payee_id == "") and (payee_name is None or payee_name == ""):
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "payee"})
            return _err("VALIDATION_ERROR", "assistant_create transactions require payee_id or payee_name", rule="((payee_id is not null) or (payee_name is not null)) for source='assistant_create'")

    # Apply patch (NO SUCCESS WITHOUT EFFECT)
    changed = False
    now = _utcnow()

    def _set(field, value):
        nonlocal changed
        if value is None:
            # explicit null allowed for nullable fields; apply if different
            if txn.get(field) is not None:
                txn[field] = None
                changed = True
            return
        if txn.get(field) != value:
            txn[field] = value
            changed = True

    if new_date is not None:
        _set("date", new_date)
    if "amount_milliunits" in patch:
        _set("amount_milliunits", patch.get("amount_milliunits"))
    if "payee_id" in patch:
        _set("payee_id", patch.get("payee_id"))
    if "payee_name" in patch:
        _set("payee_name", patch.get("payee_name"))
    if "category_id" in patch:
        _set("category_id", patch.get("category_id"))
    if "memo" in patch:
        _set("memo", patch.get("memo"))
    if new_cleared is not None:
        _set("cleared", new_cleared)
    if "approved" in patch:
        ap = patch.get("approved")
        if not isinstance(ap, bool):
            _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="VALIDATION_ERROR", meta={"field": "approved"})
            return _err("VALIDATION_ERROR", "approved must be a boolean", field="approved")
        _set("approved", ap)
    if new_status is not None:
        _set("status", new_status)
        if new_status == "deleted":
            _set("deleted", True)

    if not changed:
        _append_log("error", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code="CONFLICT")
        return _err("CONFLICT", "No changes applied; patch did not modify any fields")

    txn["updated_at"] = _iso(now)
    if txn.get("created_at") is None:
        txn["created_at"] = _iso(now)

    txns[t_idx] = txn
    _save("transactions.json", txns)

    _append_log("ok", credential_id=credential_id, connection_id=credential_id, transaction_id=transaction_id, error_code=None)
    return {"transaction": txn}
